using Tomlyn;using Tomlyn.Model; namespace VtuberBot.Core; public sealed class ConfigException:Exception{public ConfigException(string m,Exception?e=null):base(m,e){}} public sealed record AppConfig(string Name,string DatabasePath,string BaseDirectory,LogLevel LogLevel,string?ConfigPath){public string LogDirectory=>Path.Combine(BaseDirectory,"logs");public static AppConfig Load(string?cp=null){var p=cp is null?Path.Combine(AppContext.BaseDirectory,"config.toml"):Path.GetFullPath(cp);TomlTable r;try{r=File.Exists(p)?TomlSerializer.Deserialize<TomlTable>(File.ReadAllText(p))??new():new();}catch(Exception e){throw new ConfigException($"Invalid TOML in {p}: {e.Message}",e);}TomlTable T(string n)=>r.TryGetValue(n,out var v)&&v is TomlTable t?t:throw new ConfigException($"[{n}] must be a TOML table.");string S(TomlTable t,string k,string d)=>!t.TryGetValue(k,out var v)?d:v as string??throw new ConfigException($"[{k}] must be a string.");var b=cp is null?AppContext.BaseDirectory:Path.GetDirectoryName(p)!;var n=S(T("app"),"name","VTuber Bot");var db=S(T("database"),"path",Path.Combine("data","vtuber.sqlite3"));var lv=S(T("logging"),"level","INFO");if(string.IsNullOrWhiteSpace(n)||!Enum.TryParse(lv,true,out LogLevel l))throw new ConfigException("Invalid configuration.");return new(n.Trim(),Path.GetFullPath(db,b),b,l,File.Exists(p)?p:null);}}